contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will take two parameters: an arbitrary bytes32 guessHash and a uint numAdvanceBlocks
    // numAdvanceBlocks >= 1 means we attempt to wait at least that many blocks before calling settle.
    // Also take amounts for lockIn (must be exactly 1 ether) and for constructor funding to ensure balance.
    function run(bytes32 guessHash, uint numAdvanceBlocks, uint lockValue, uint settleValue) public payable {
        require(address(this).balance >= lockValue + settleValue, "insufficient balance for transfers");
        // Preconditions on values we will send to c
        // lockInGuess requires exactly 1 ether and initial guesses[msg.sender].block == 0
        // settle requires no value, but we allow caller to pass settleValue which we won't send to settle; it's just observable
        // Enforce lockValue equals 1 ether to exercise the normal path; if it isn't 1 ether we expect lockInGuess to revert.

        bool lockReverted;
        try c.lockInGuess{value: lockValue}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Observe contract balance after lock attempt
        uint balAfterLock = address(c).balance;
        // Record our balance as well
        uint myBalAfterLock = address(this).balance;

        // Now attempt to call settle exactly once. It may revert if preconditions not met.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        uint balAfterSettle = address(c).balance;
        uint myBalAfterSettle = address(this).balance;

        // General invariant to assert:
        // If lockInGuess reverted then c's balance should be unchanged by that call (it didn't accept ether),
        // and settle cannot have transferred us funds (since we never locked in). If lockInGuess succeeded (did not revert)
        // then lockValue must have been exactly 1 ether (because the contract enforces it). After that,
        // settle can only increase our balance by at most 2 ether and only if it did not revert and only if the stored guess equaled the blockhash; but we cannot read internal stored guess — instead we assert that if we received any funds from c (myBalAfterSettle > myBalAfterLock)
        // then lockInGuess must not have reverted and settle must not have reverted, and the net increase from c to us is <= 2 ether and c's balance decreased accordingly.

        assert(
            (
                // Case A: lock reverted
                lockReverted
                ? (
                    // then c's balance didn't increase by lockValue and we didn't receive funds from settle
                    balAfterLock + 0 == address(c).balance && myBalAfterSettle <= myBalAfterLock
                )
                : (
                    // Case B: lock succeeded
                    // then lockValue was 1 ether and c.balance increased by 1 at least (may have had constructor funds)
                    lockValue == 1 ether
                    // If we later received funds from c, then settle didn't revert and c's balance decreased by at least that amount
                    && (
                        (myBalAfterSettle > myBalAfterLock) ? (!settleReverted && balAfterSettle + (myBalAfterSettle - myBalAfterLock) == balAfterLock) : true
                    )
                    // Also any funds we received from c in this transaction cannot exceed 2 ether
                    && (myBalAfterSettle - myBalAfterLock <= 2 ether)
                )
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Parameters:
    // - guessHash: bytes32 to pass to lockInGuess
    // - lockValue: amount of wei to send to lockInGuess (we will require it equals 1 ether to exercise normal path)
    function run(bytes32 guessHash, uint lockValue) public payable {
        // only require about our parameters/balance; do not require anything about c's internals
        require(address(this).balance >= lockValue, "insufficient balance to send");

        bool lockReverted;
        uint balBefore = address(c).balance;
        // Attempt lockInGuess; it may revert
        try c.lockInGuess{value: lockValue}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        uint balAfterLock = address(c).balance;
        // Now attempt to call settle; it may revert
        bool settleReverted;
        uint myBalBeforeSettle = address(this).balance;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }
        uint balAfterSettle = address(c).balance;
        uint myBalAfterSettle = address(this).balance;

        // Assert a general invariant about successful lockInGuess and effects:
        // - If lockInGuess succeeded then lockValue must have been exactly 1 ether and c.balance increased by exactly lockValue.
        // - If lockInGuess succeeded then any funds we later receive from settle (myBalAfterSettle - myBalBeforeSettle) are <= 2 ether,
        //   and c's balance decreased by exactly that received amount (conservation of Ether between c and this contract in this tx).
        // - If lockInGuess reverted then c.balance did not increase because of that call (balAfterLock == balBefore).

        assert(
            (
                // lock reverted: contract balance unchanged by lock attempt
                lockReverted
                ? (balAfterLock == balBefore)
                : (
                    // lock succeeded: lockValue must have been 1 ether and c.balance increased by lockValue
                    lockValue == 1 ether && balAfterLock == balBefore + lockValue
                    // any funds received from c after settle are <= 2 ether and c lost exactly that amount
                    && (myBalAfterSettle >= myBalBeforeSettle ? (myBalAfterSettle - myBalBeforeSettle) <= 2 ether : true)
                    && (balAfterSettle + (myBalAfterSettle - myBalBeforeSettle) == balAfterLock)
                )
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Parameters:
    // - guessHash: bytes32 to pass to lockInGuess
    // - lockValue: wei to send to lockInGuess
    function run(bytes32 guessHash, uint lockValue) public payable {
        // only require about our ability to send Ether
        require(address(this).balance >= lockValue, "insufficient balance to send");

        uint balBefore = address(c).balance;

        bool lockReverted;
        // Call lockInGuess; it may revert.
        try c.lockInGuess{value: lockValue}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        uint balAfter = address(c).balance;

        // Read the public getter for guesses mapping: C.guesses is public? (struct not public) -- Cannot access struct directly.
        // The mapping in C is not declared public, but we can observe effects via block number getter by attempting to call settle conditions:
        // However the contract C does not expose the stored block number; but it does expose behaviour via settle and via c.balance.
        // We will use the publicly observable rule: if lock succeeded then c.balance increased by lockValue and lockValue must equal 1 ether.
        // Also if lock succeeded then the stored block for this address was set to non-zero which prevents immediate re-lock; consequently a second lock attempt should revert.

        // Attempt a second lockInGuess with same value and catch whether it reverts. If the first succeeded and set a future block, the second call must revert because require(guesses[msg.sender].block == 0) fails.
        bool secondLockReverted;
        // ensure we have funds to attempt second call
        require(address(this).balance >= lockValue, "insufficient balance for second attempt");
        try c.lockInGuess{value: lockValue}(guessHash) {
            secondLockReverted = false;
        } catch {
            secondLockReverted = true;
        }

        // Now assert a general rule relating the observed effects:
        // - If the first lock reverted then c.balance did not increase (balAfter == balBefore) and the second attempt did not consume funds (i.e., if secondLockReverted then balance unchanged, else changed by lockValue).
        // - If the first lock succeeded then lockValue must have been exactly 1 ether, c.balance increased by exactly lockValue, and the immediate second lock must revert (because stored block != 0).
        assert(
            (
                lockReverted
                ? (
                    // first reverted -> c.balance unchanged
                    balAfter == balBefore
                )
                : (
                    // first succeeded -> must have been exactly 1 ether and c.balance increased by lockValue,
                    // and second attempt must revert due to non-zero stored block
                    lockValue == 1 ether
                    && balAfter == balBefore + lockValue
                    && secondLockReverted
                )
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params:
    // - guessHash: bytes32 to pass to lockInGuess
    // - lockValue: wei to send to lockInGuess (we'll allow any but observe behavior)
    function run(bytes32 guessHash, uint lockValue) public payable {
        // only require that this contract can fund the lock call if we intend to send Ether
        require(address(this).balance >= lockValue, "insufficient balance to send");

        // Record c balance before any interaction
        uint balBefore = address(c).balance;

        bool firstReverted;
        // attempt to lock in a guess; it may revert
        try c.lockInGuess{value: lockValue}(guessHash) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // balance immediately after lock attempt
        uint balAfterLock = address(c).balance;

        // Now attempt to call settle; it may revert. We must catch that.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        uint balAfterSettle = address(c).balance;

        // General rule asserted:
        // - If lockInGuess reverted then c's balance did not change because of it (balAfterLock == balBefore), and settle may or may not revert but cannot decrease c.balance below balBefore (i.e., balAfterSettle >= balBefore - 2 ether is trivial but we require a stronger invariant below tailored to behavior): since no successful lock was recorded for this sender, settle cannot pay this sender 2 ether, so balAfterSettle == balAfterLock.
        // - If lockInGuess succeeded then lockValue must have been exactly 1 ether and balAfterLock == balBefore + 1 ether. After calling settle (in same transaction) either:
        //     * settle reverted (so c.balance remains balAfterLock), or
        //     * settle did not revert and paid out at most 2 ether and only by paying exactly 2 ether when the stored guess equaled the blockhash; because payments only occur when non-zero blockhash equals guess, the balance after settle is either unchanged or decreased by exactly 2 ether.
        // Combining these observations into a single general assertion:
        assert(
            (
                firstReverted
                ? (
                    // if first reverted then the lock did not change c balance, and settle cannot have decreased c.balance (no payout for us)
                    balAfterLock == balBefore
                    && balAfterSettle == balAfterLock
                )
                : (
                    // lock succeeded: must have been exactly 1 ether and c balance increased by that amount
                    lockValue == 1 ether
                    && balAfterLock == balBefore + 1 ether
                    // and settle either reverted leaving balance unchanged, or succeeded and decreased by at most 2 ether and only in the discrete step of 2 ether
                    && (
                        settleReverted
                        ? (balAfterSettle == balAfterLock)
                        : (
                            // settle succeeded: balance is either unchanged or exactly decreased by 2 ether
                            (balAfterSettle == balAfterLock) || (balAfterSettle + 2 ether == balAfterLock)
                        )
                    )
                )
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params:
    // - guessHash: bytes32 to pass to lockInGuess
    // - lockValue: wei to send to lockInGuess
    function run(bytes32 guessHash, uint lockValue) public payable {
        require(address(this).balance >= lockValue, "insufficient balance to send");

        // Record c balance before any interaction
        uint balBefore = address(c).balance;

        bool lockReverted;
        try c.lockInGuess{value: lockValue}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        uint balAfterLock = address(c).balance;

        // Now attempt to call settle; it may revert and it may or may not transfer funds to this contract
        bool settleReverted;
        uint testerBalBeforeSettle = address(this).balance;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }
        uint testerBalAfterSettle = address(this).balance;
        uint balAfterSettle = address(c).balance;

        // If settle succeeded and our tester balance increased by exactly 2 ether, then:
        //  - lockInGuess must have succeeded (otherwise nothing was locked and settle cannot pay us)
        //  - the contract c must have had at least 2 ether available to pay (i.e., its balance before settle was >= 2 ether)
        // We express this as a single assert over observable values and revert flags.
        assert(
            (
                // case: settle did not revert and tester gained exactly 2 ether
                (!settleReverted && testerBalAfterSettle == testerBalBeforeSettle + 2 ether)
                ? (
                    // then lock must have succeeded
                    !lockReverted
                    // and c must have had enough funds to pay: its balance before settle equals balAfterLock and must be >= 2 ether
                    && balAfterLock >= 2 ether
                    // and c's balance after settle decreased by exactly 2 ether
                    && balAfterSettle + 2 ether == balAfterLock
                )
                : (
                    // otherwise we place no additional constraint (other behaviors allowed)
                    true
                )
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: hash to lock, and amount to send when locking (must be 1 ether to succeed)
    function run(bytes32 h, uint256 amount) public payable {
        require(address(this).balance >= amount);
        // Initially ensure our slot is empty (we observe via the public getter auto-generated for mapping)
        // The getter signature for guesses is guesses(address) returns (uint256, bytes32)
        (uint256 beforeBlock, bytes32 beforeGuess) = c.guesses(address(this));

        // We require that beforeBlock is 0 so we can attempt a lock; if it's non-zero then lockInGuess would revert
        // but we want to exercise both successful lock and settle behavior, so only proceed if empty
        require(beforeBlock == 0);

        // Try to lock in a guess. This may revert if amount != 1 ether. Capture whether it reverted.
        bool lockedReverted;
        try c.lockInGuess{value: amount}(h) {
            lockedReverted = false;
        } catch {
            lockedReverted = true;
        }

        // Read state after trying to lock
        (uint256 afterBlock, bytes32 afterGuess) = c.guesses(address(this));

        // If lock did not revert then afterBlock should be non-zero and equal to block.number + 1 at the time of call.
        // We cannot refer to the historical block.number at call time, so we only assert a general invariant about settle:
        // Call settle (may revert if no guess or block not passed); capture revert flag.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Read state after settle attempt
        (uint256 finalBlock, bytes32 finalGuess) = c.guesses(address(this));

        // General rule: if lockInGuess succeeded (i.e., lockedReverted == false) then after a call to settle() the stored entry must be cleared (block == 0).
        // If lockInGuess reverted, we cannot require anything about final state from this sequence.
        assert(lockedReverted || finalBlock == 0);
    }

    receive() external payable {}
}

