contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We cannot directly read the private mapping, so we assert observable consequences:
    // If lockInGuess succeeds, then amount == 1 ether, c's balance increases by 1 ether,
    // and a subsequent settle call by this contract will not revert with "guesses[msg.sender].block == 0" (i.e., it has a stored guess entry to attempt to settle).
    function run(bytes32 h, uint256 amount) public payable {
        require(address(this).balance >= amount);

        uint256 balBefore = address(c).balance;

        bool lockReverted;
        try c.lockInGuess{value: amount}(h) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        uint256 balAfter = address(c).balance;

        // Now attempt to call settle and record whether it reverts and the reason in a coarse way.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // General rule: either lockInGuess reverted, or (it succeeded and amount == 1 ether and balance increased by 1 ether
        // and settle does NOT revert with the "no guess" requirement). We cannot distinguish different revert reasons, but if lockInGuess succeeded
        // the contract must have recorded a guess entry so that settle() is callable (i.e., does not revert immediately with missing guess).
        assert(lockReverted || (amount == 1 ether && balAfter == balBefore + 1 ether && !settleReverted));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We take two parameters: a candidate hash to lock and an amount to send when locking (must be 1 ether to succeed),
    // and a boolean indicating whether to call settle afterwards. The function is payable so the test can hold ETH
    // and forward it to c.
    function run(bytes32 candidate, uint256 lockAmount, bool doSettle) public payable {
        // ensure this test contract has enough balance to send lockAmount
        require(address(this).balance >= lockAmount);
        // Precondition: lockAmount must be exactly 1 ether for lockInGuess to succeed (otherwise it should revert).
        // We don't restrict inputs further; we'll observe revert behavior.

        // Record c and test balances before any calls
        uint256 cBalanceBefore = address(c).balance;

        // Try to call lockInGuess and capture whether it reverted
        bool lockReverted;
        try c.lockInGuess{value: lockAmount}(candidate) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // After attempting lockInGuess, observe whether the guess mapping for this caller reports a block value
        // The auto-generated getter for guesses is guesses(address) returning (uint, bytes32)
        (uint256 storedBlock, bytes32 storedGuess) = c.guesses(address(this));

        // If lockInGuess did not revert, then it must have been called with exactly 1 ether and when previous block was zero.
        // In that case, storedBlock must be nonzero and should equal the block number at which it was set (which is current block + 1 at the time of the call).
        // We cannot read the historical block number at the time of call, but we can assert storedBlock > block.number - 1 (i.e., >= block.number)
        // However, to be conservative and general: if lockInGuess succeeded, storedBlock must be != 0.

        // Optionally call settle and capture whether it reverted
        bool settleReverted = false;
        uint256 cBalanceAfterSettle = cBalanceBefore;
        if (doSettle) {
            try c.settle() {
                settleReverted = false;
            } catch {
                settleReverted = true;
            }
            cBalanceAfterSettle = address(c).balance;
        }

        // General rule assert combining observations:
        // 1) If lockInGuess succeeded then storedBlock != 0 and storedGuess equals candidate.
        // 2) If lockInGuess reverted then storedBlock == 0 (no new lock recorded by a failed call).
        // 3) If settle was called and did not revert and it paid out, then c's balance decreased by exactly 2 ether and our balance increased accordingly.
        //    Since we cannot check this contract's balance increase directly (address(this).balance changed by the external transfer), we at least assert
        //    that c's balance did not increase as a result of a successful payout. We'll express a safe observable: if settle did not revert and c's balance decreased,
        //    then previously storedGuess must have equaled the blockhash at storedBlock (we observe storedGuess and storedBlock). If settle reverted, no payout occurred.

        // We now encode a single assert that is a conjunction capturing these relations.
        // Note: avoid underflow; use comparisons only.
        assert(
            // case A: lock reverted -> no stored lock
            (lockReverted && storedBlock == 0)
            ||
            // case B: lock succeeded -> storedBlock != 0 and storedGuess == candidate
            (!lockReverted && storedBlock != 0 && storedGuess == candidate)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We take the candidate hash and the amount to send when locking. Must have balance for the amount.
    function run(bytes32 candidate, uint256 lockAmount) public payable {
        require(address(this).balance >= lockAmount);

        // balance of contract c before call
        uint256 cBalBefore = address(c).balance;

        // Try to call lockInGuess and capture whether it reverted
        bool lockReverted;
        try c.lockInGuess{value: lockAmount}(candidate) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Observe public surface: we can read address(c).balance and cannot read internal mapping directly.
        // The contract C does NOT expose a public getter for the mapping name 'guesses' (it's not declared public),
        // so instead we rely on observable effects on c's balance to infer outcomes together with revert flag.

        // If lockInGuess succeeded it requires msg.value == 1 ether and previously guesses[msg.sender].block == 0.
        // The observable consequence is that c's balance increased by exactly 1 ether when the call succeeded,
        // and did not increase when the call reverted.
        uint256 cBalAfter = address(c).balance;

        // The general rule: (1) if lockInGuess succeeded then c balance increased by 1 ether; (2) if it reverted then c balance unchanged.
        // Expressed as a single assert combining the revert flag and observed balance change.
        assert(
            (lockReverted && cBalAfter == cBalBefore)
            ||
            (!lockReverted && cBalAfter == cBalBefore + 1 ether)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We take a candidate hash and provide amounts to lock; we also allow an independent amount to fund this contract.
    // lockAmount should be the amount we send to lockInGuess; fundAmount is sent to this contract before using it (must be >= lockAmount).
    function run(bytes32 candidate, uint256 lockAmount, uint256 fundAmount) public payable {
        // Ensure the test contract has enough balance to attempt lockInGuess with lockAmount.
        require(address(this).balance + fundAmount >= lockAmount);

        // If caller supplied fundAmount as msg.value, it is already available in this contract's balance.
        // No external sending is performed; the test relies only on its own balance and sending to c.

        // Record balance of this test contract before any calls to c
        uint256 balBefore = address(this).balance;

        // Try to call lockInGuess; this may revert if conditions in C are not met.
        bool lockReverted;
        // Ensure we have the funds (if lockAmount > 0)
        if (lockAmount > 0) {
            require(address(this).balance >= lockAmount);
        }
        try c.lockInGuess{value: lockAmount}(candidate) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Now call settle which may also revert; capture whether it reverted.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

