contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We take parameters to drive lockInGuess: the hash to lock and the amount to send (must be 1 ether)
    // and a flag whether to call settle afterwards. The test asserts the general invariant about payout
    // and state clearing described in property_summary.
    function run(bytes32 guessedHash, uint256 amount, bool callSettle) public payable {
        require(amount == 1 ether);
        // ensure this contract has enough balance to send
        require(address(this).balance >= amount);

        // Before any action, note balances
        uint256 balC_before = address(c).balance;
        uint256 balThis_before = address(this).balance;

        // Attempt to lock in the guess; capture whether it reverted
        bool lockReverted;
        try c.lockInGuess{value: amount}(guessedHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Read public observable: guesses mapping getter exists as guesses(address) returning (uint,bytes32)
        (uint256 gblock_after, bytes32 gguess_after) = c.guesses(address(this));

        // Optionally call settle and capture revert
        bool settleReverted = true;
        if (callSettle) {
            try c.settle() {
                settleReverted = false;
            } catch {
                settleReverted = true;
            }
        }

        // Read balances after actions
        uint256 balC_after = address(c).balance;
        uint256 balThis_after = address(this).balance;

        /* General rule asserted:
           - If lockInGuess reverted then c's balance unchanged and no guess recorded for this address.
           - If lockInGuess succeeded then c.balance increased by 1 ether and the guesses mapping records a non-zero block number > 0 equal to current stored block (we observe gblock_after != 0).
           - If settle was called and it did not revert, then the guesses entry for this address must have been cleared (block == 0) afterwards.
           - Furthermore, if settle did not revert and the contract paid out 2 ether to this contract, that can only happen when the recorded guess matched blockhash of the recorded block (we cannot call blockhash here, but we can assert that any increase of this contract's balance by exactly 2 ether implies that previously lockInGuess succeeded and settle succeeded and the guesses entry was cleared).

           We express these relations purely with observable values and revert flags.
        */

        // Compose the assertion as one boolean expression.
        assert(
            // If lock reverted: balances unchanged and no recorded guess
            (lockReverted && balC_after == balC_before && balThis_after == balThis_before && gblock_after == 0)
            ||
            // If lock succeeded: c gained 1 ether and mapping shows a stored block number > 0
            (
                !lockReverted
                && balC_after == balC_before + 1 ether
                && balThis_after == balThis_before - 1 ether
                && gblock_after != 0
                && (
                    // Now consider settle not called: nothing about clearing needed
                    (!callSettle)
                    ||
                    // If settle was called and reverted: then either balances reflect no payout or revert prevented state change; we allow either outcome
                    (callSettle && settleReverted)
                    ||
                    // If settle was called and did not revert: mapping must be cleared and balances reflect either a 2 ether payout or no payout
                    (callSettle && !settleReverted && gblock_after == 0 && (
                        // If the contract paid out 2 ether, this contract's balance increased by 2 ether net relative to after lock (i.e., balThis_after == balThis_before -1 ether + 2 ether)
                        (balThis_after == balThis_before - 1 ether + 2 ether && balC_after == balC_before - 1 ether)
                        // Or if no payout occurred then balances remain as after lock: balThis_after == balThis_before -1 ether
                        || (balThis_after == balThis_before - 1 ether && balC_after == balC_before + 1 ether)
                    ))
                )
            )
        );
    }

    // Allow receiving ether when settle transfers funds
    receive() external payable {}
}

