        bytes32 sample = keccak256(abi.encodePacked(address(this), block.number, amount));
        try c.lockInGuess{value: amount}(sample) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // record balances after lock attempt (and before optional settle)
        uint256 balC_mid = address(c).balance;
        uint256 balThis_mid = address(this).balance;

        // attempt settle if requested
        bool settleReverted = true;
        if (callSettle) {
            try c.settle() {
                settleReverted = false;
            } catch {
                settleReverted = true;
            }
        }

        // final balances
        uint256 balC_after = address(c).balance;
        uint256 balThis_after = address(this).balance;

        // Assert one general invariant about transfers and reverts, observable via balances and revert flags:
        // - If lockInGuess reverted, no balance change occurred on either side (call did not accept 1 ether).
        // - If lockInGuess succeeded, then after that call C's balance increased by exactly 1 ether and this contract decreased by 1 ether.
        // - If settle was not called, final balances equal mid balances.
        // - If settle was called and it reverted, final balances equal mid balances (no effect due to revert).
        // - If settle was called and it succeeded, then the only allowed change from mid to after is either a payment of 2 ether from C to this contract (C -2 ether, this +2 ether) or no net payment (balances unchanged), i.e., settle cannot produce other arbitrary balance changes.
        assert(
            // Case A: lock reverted -> no change at all
            (lockReverted
                && balC_mid == balC_before
                && balThis_mid == balThis_before
                && balC_after == balC_before
                && balThis_after == balThis_before)
            ||
            // Case B: lock succeeded
            (!lockReverted
                && balC_mid == balC_before + 1 ether
                && balThis_mid == balThis_before - 1 ether
                && (
                    // B1: settle not called -> final == mid
                    (!callSettle && balC_after == balC_mid && balThis_after == balThis_mid)
                    ||
                    // B2: settle called but reverted -> final == mid
                    (callSettle && settleReverted && balC_after == balC_mid && balThis_after == balThis_mid)
                    ||
                    // B3: settle called and succeeded -> either C paid out 2 ether or no payout; so final balances are either mid (no payout)
                    // or (balC_after == balC_mid - 2 ether && balThis_after == balThis_mid + 2 ether)
                    (callSettle && !settleReverted && (
                        (balC_after == balC_mid && balThis_after == balThis_mid)
                        || (balC_after == balC_mid - 2 ether && balThis_after == balThis_mid + 2 ether)
                    ))
                )
            )
        );
    }

    // allow receiving ether from C.settle pay-out
    receive() external payable {}
}

