contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // params: hash to lock, amount to send when locking (must be 1 ether to succeed),
    // and a dummy extra call flag to optionally avoid calling settle when preconditions fail.
    function run(bytes32 lockHash, uint lockAmount, bool callSettle) public payable {
        require(address(this).balance >= lockAmount);
        // Ensure the test pays exactly via parameter when trying to lock
        bool lockedReverted;
        try c.lockInGuess{value: lockAmount}(lockHash) {
            lockedReverted = false;
        } catch {
            lockedReverted = true;
        }

        // Read observable state: the mapping has a public getter auto-generated with signature guesses(address)
        // Which returns (uint, bytes32) corresponding to (block, guess). We can call it to inspect before settle.
        (uint storedBlockBefore, bytes32 storedGuessBefore) = c.guesses(address(this));

        bool settledReverted = true; // default if we don't call
        uint balBefore = address(c).balance;
        uint myBalBefore = address(this).balance;

        if (callSettle) {
            try c.settle() {
                settledReverted = false;
            } catch {
                settledReverted = true;
            }
        }

        // Read observable state after settle (or after failed attempt)
        (uint storedBlockAfter, bytes32 storedGuessAfter) = c.guesses(address(this));
        uint balAfter = address(c).balance;
        uint myBalAfter = address(this).balance;

        // General invariant to assert:
        // 1) If lockInGuess reverted, then nothing was recorded: storedBlockBefore == 0 and storedGuessBefore == bytes32(0).
        //    And settle (if called) must revert because there is no guess locked (settle requires block != 0).
        // 2) If lockInGuess succeeded, then storedBlockBefore != 0 and storedGuessBefore == lockHash.
        //    After calling settle (if it was attempted), the storedBlockAfter must be 0 (entry cleared).
        // 3) If settle was called and did not revert, then either:
        //      - If the recorded block's blockhash was nonzero and equals the guess, the contract paid out 2 ether to caller
        //        (so contract balance decreased by 2 ether and caller balance increased by 2 ether), OR
        //      - Otherwise the contract balance did not decrease due to payout (i.e., balAfter >= balBefore - 0)
        // Note: We cannot directly read blockhash from outside, so we encode the relation via balances and returned stored values.

        bool case1 = (lockedReverted && storedBlockBefore == 0 && storedGuessBefore == bytes32(0) && (callSettle ? settledReverted : true));

        bool case2_locked = (!lockedReverted && storedBlockBefore != 0 && storedGuessBefore == lockHash);
        bool case2_afterCleared = (!lockedReverted && (!callSettle || storedBlockAfter == 0));

        // If settle succeeded (did not revert), then either contract lost exactly 2 ether (payout) and caller gained 2 ether,
        // or contract balance did not decrease (no payout). We assert that these are the only possibilities.
        bool payoutObserved = (!settledReverted && balBefore >= 2 ether && balAfter == balBefore - 2 ether && myBalAfter == myBalBefore + 2 ether);
        bool noPayoutObserved = (!settledReverted && balAfter == balBefore && myBalAfter == myBalBefore);

        bool settleConsistent = (!callSettle) || (callSettle && (settledReverted || payoutObserved || noPayoutObserved));

        // Combine all conditions into one general rule
        assert(case1 || (case2_locked && case2_afterCleared && settleConsistent));
    }

    receive() external payable {}
}

