        // Rule construction:
        // If lockInGuess reverted, then it must have been because either the sent value wasn't exactly 1 ether
        // or there was already a lock; in that case, balances remained unchanged by lockInGuess attempt.
        bool lock_failed_no_balance_change = lockReverted && balAfter == balBefore && myBalAfter == myBalBefore;

