        bool observed_payout = (!settleReverted && balBefore >= 2 ether && balAfter == balBefore - 2 ether && myBalAfter == myBalBefore + 2 ether);
        bool observed_no_payout = (!settleReverted && balAfter == balBefore && myBalAfter == myBalBefore);

        // If settle was not called, balances after should equal balances before (no change from settle step)
        bool no_settle_called_balance_constant = (!doSettle) && balAfter == balBefore && myBalAfter == myBalBefore;

        // Combine into one general assertion:
        // Either the lock failed and nothing changed, or the lock succeeded and then either we didn't call settle (so balances unchanged now),
        // or we called settle and it either reverted, or produced exactly the documented two possibilities (payout or no payout).
        assert(
            lock_failed_no_balance_change
            || (
                !lockReverted && (
                    no_settle_called_balance_constant
                    || settleReverted
                    || observed_payout
                    || observed_no_payout
                )
            )
