        uint contractBal_before = address(c).balance;
        uint myBal_before = address(this).balance;

        // Attempt lockInGuess as a top-level state-changing call, capturing revert via try/catch
        bool lockReverted;
        try c.lockInGuess{value: lockAmount}(lockHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Balances after lock attempt (and before optional settle)
        uint contractBal_afterLock = address(c).balance;
        uint myBal_afterLock = address(this).balance;

        // Optionally call settle as a top-level state-changing call, capturing revert
        bool settleCalled = doSettle;
        bool settleReverted = false;
        if (settleCalled) {
            try c.settle() {
                settleReverted = false;
            } catch {
                settleReverted = true;
            }
        }

        // Final observed balances
        uint contractBal_final = address(c).balance;
        uint myBal_final = address(this).balance;

        // Conditions:
        // 1) If lock reverted, then lock attempt made no net transfer: balances unchanged by that attempt
        bool lock_revert_no_transfer = lockReverted && contractBal_afterLock == contractBal_before && myBal_afterLock == myBal_before;

        // 2) If lock succeeded, it must have required exactly 1 ether; i.e., lockAmount == 1 ether AND contract gained exactly 1 ether from the lock call
        bool lock_succeeded_and_expected = (!lockReverted) && (lockAmount == 1 ether) && (contractBal_afterLock == contractBal_before + 1 ether) && (myBal_afterLock == myBal_before - 1 ether);

        // 3) Effects of settle when called after lock (observed between afterLock and final):
        //    - If settle was not called, balances must remain as afterLock
        bool no_settle_observed = (!settleCalled) && (contractBal_final == contractBal_afterLock) && (myBal_final == myBal_afterLock);

        //    - If settle called and reverted, balances remain as afterLock
        bool settle_reverted_observed = (settleCalled && settleReverted) && (contractBal_final == contractBal_afterLock) && (myBal_final == myBal_afterLock);

        //    - If settle called and did not revert, either it paid out 2 ether to this contract (contract -2, me +2) or did nothing
        bool settle_succeeded_payout = (settleCalled && !settleReverted) && (contractBal_final + 2 ether == contractBal_afterLock) && (myBal_final == myBal_afterLock + 2 ether);
        bool settle_succeeded_no_payout = (settleCalled && !settleReverted) && (contractBal_final == contractBal_afterLock) && (myBal_final == myBal_afterLock);

        // Combine into the single general assertion describing allowed behaviors
        assert(
            // Either the lock reverted and changed nothing
            lock_revert_no_transfer
            ||
            // Or the lock succeeded with exactly 1 ether and subsequent settle behavior is one of the allowed outcomes
            (
                lock_succeeded_and_expected && (
                    no_settle_observed || settle_reverted_observed || settle_succeeded_payout || settle_succeeded_no_payout
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
