            } catch {
                settleReverted = true;
            }
        }

        // final balances
        uint bal_c_final = address(c).balance;
        uint bal_me_final = address(this).balance;

        // Conditions to assert as a single general rule:
        // If lock reverted => no balance change from the lock call
        bool lock_revert_no_transfer = lockReverted && bal_c_afterLock == bal_c_before && bal_me_afterLock == bal_me_before;

        // If lock succeeded => it must have been called with exactly 1 ether and contract gained exactly 1 ether
        bool lock_succeeded_and_expected = (!lockReverted) && (lockAmount == 1 ether) && (bal_c_afterLock == bal_c_before + 1 ether) && (bal_me_afterLock == bal_me_before - 1 ether);

        // Effects of settle (considering final balances relative to afterLock):
        // If settle not called => final balances equal afterLock
        bool no_settle_observed = (!settleCalled) && (bal_c_final == bal_c_afterLock) && (bal_me_final == bal_me_afterLock);

        // If settle called and reverted => balances unchanged from afterLock
        bool settle_reverted_observed = (settleCalled && settleReverted) && (bal_c_final == bal_c_afterLock) && (bal_me_final == bal_me_afterLock);

        // If settle called and succeeded => either paid out 2 ether to this contract or did nothing
        bool settle_succeeded_payout = (settleCalled && !settleReverted) && (bal_c_final + 2 ether == bal_c_afterLock) && (bal_me_final == bal_me_afterLock + 2 ether);
        bool settle_succeeded_no_payout = (settleCalled && !settleReverted) && (bal_c_final == bal_c_afterLock) && (bal_me_final == bal_me_afterLock);

        // Single general assertion combining the allowed behaviors
        assert(
